"""Convert the Markdown dialect generated by LiteParse to editable Office files."""

from dataclasses import dataclass
from html import unescape
from html.parser import HTMLParser
from io import BytesIO
import re
from xml.sax.saxutils import escape
from zipfile import ZIP_DEFLATED, ZipFile


@dataclass
class Cell:
    text: str
    columns: int = 1
    rows: int = 1
    header: bool = False


@dataclass
class Table:
    rows: list[list[Cell]]


class HTMLTable(HTMLParser):
    def __init__(self):
        super().__init__()
        self.table = Table([])
        self.cell = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "tr":
            self.table.rows.append([])
        if tag in ("td", "th") and self.table.rows:
            def span(name, limit):
                value = attrs.get(name) or ""
                return min(limit, max(1, int(value))) if re.fullmatch(r"[0-9]{1,5}", value) else 1

            self.cell = Cell("", span("colspan", 256), span("rowspan", 65535), tag == "th")
            self.table.rows[-1].append(self.cell)
        if tag == "br" and self.cell:
            self.cell.text += "\n"

    def handle_endtag(self, tag):
        if tag in ("td", "th") and self.cell:
            self.cell.text = self.cell.text.strip()
            self.cell = None

    def handle_data(self, data):
        if self.cell:
            self.cell.text += data


HTML_TABLE = re.compile(r"<table\b[^>]*>.*?</table\s*>", re.I | re.S)
RULE = re.compile(r"\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)*\|?")
HEADING = re.compile(r"^(#{1,6})\s+(.+)")


def split_row(line):
    line = line.strip().removeprefix("|")
    if line.endswith("|") and not line.endswith(r"\|"):
        line = line[:-1]
    cells = re.split(r"(?<!\\)\|", line)
    return [unescape(re.sub(r"<br\s*/?>", "\n", cell.strip().replace(r"\|", "|"), flags=re.I))
            for cell in cells]


def markdown_blocks(markdown):
    cursor = 0
    for match in HTML_TABLE.finditer(markdown):
        yield from text_blocks(markdown[cursor:match.start()])
        parser = HTMLTable()
        parser.feed(match.group())
        if any(parser.table.rows):
            yield parser.table
        cursor = match.end()
    yield from text_blocks(markdown[cursor:])


def text_blocks(markdown):
    lines = markdown.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line or re.fullmatch(r"[-*_]{3,}", line):
            i += 1
            continue
        if "|" in line and i + 1 < len(lines) and RULE.fullmatch(lines[i + 1].strip()):
            rows = [[Cell(value, header=True) for value in split_row(line)]]
            i += 2
            while i < len(lines) and "|" in lines[i] and lines[i].strip():
                rows.append([Cell(value) for value in split_row(lines[i])])
                i += 1
            yield Table(rows)
            continue
        heading = HEADING.fullmatch(line)
        if heading:
            yield (len(heading[1]), unescape(heading[2]))
        else:
            yield (0, unescape(re.sub(r"^[-*+]\s+", "• ", line)))
        i += 1


def positioned(table):
    occupied_until = {}
    count = len(table.rows)
    for y, row in enumerate(table.rows):
        x = 0
        for cell in row:
            while any(occupied_until.get(col, 0) > y for col in range(x, x + cell.columns)):
                x += 1
                if x + cell.columns > 16384:
                    raise ValueError("Table has too many columns.")
            height = min(cell.rows, count - y)
            if x + cell.columns > 16384:
                raise ValueError("Table has too many columns.")
            yield y, x, cell, height
            for col in range(x, x + cell.columns):
                occupied_until[col] = y + height
            x += cell.columns


def xml_text(value):
    return escape("".join(char for char in value if char in "\n\t\r"
                          or 32 <= ord(char) <= 0xD7FF or 0xE000 <= ord(char) <= 0xFFFD
                          or 0x10000 <= ord(char) <= 0x10FFFF))


OFFICE = "http://schemas.openxmlformats.org"
TYPES = OFFICE + "/package/2006/content-types"
RELS = OFFICE + "/package/2006/relationships"
DOCREL = OFFICE + "/officeDocument/2006/relationships"
WORD = OFFICE + "/wordprocessingml/2006/main"
SHEET = OFFICE + "/spreadsheetml/2006/main"
DECL = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'


def package(main, entries):
    stream = BytesIO()
    with ZipFile(stream, "w", ZIP_DEFLATED) as archive:
        overrides = []
        for name, kind, content in entries:
            archive.writestr(name, DECL + content)
            if kind:
                overrides.append(f'<Override PartName="/{name}" ContentType="application/vnd.openxmlformats-officedocument.{kind}+xml"/>')
        archive.writestr("[Content_Types].xml", DECL + f'<Types xmlns="{TYPES}">'
                         f'<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                         f'<Default Extension="xml" ContentType="application/xml"/>{"".join(overrides)}</Types>')
        archive.writestr("_rels/.rels", DECL + f'<Relationships xmlns="{RELS}">'
                         f'<Relationship Id="rId1" Type="{DOCREL}/officeDocument" Target="{main}"/>'
                         '</Relationships>')
    return stream.getvalue()


def paragraph(text, level=0, header=False):
    properties = '<w:rPr><w:b/></w:rPr>' if header else ""
    if level:
        properties = f'<w:rPr><w:b/><w:sz w:val="{max(24, 40 - 4 * level)}"/></w:rPr>'
    run = '<w:br/>'.join(f'<w:t xml:space="preserve">{xml_text(line)}</w:t>'
                         for line in text.split("\n"))
    outline = f'<w:pPr><w:outlineLvl w:val="{level - 1}"/></w:pPr>' if level else ""
    return f"<w:p>{outline}<w:r>{properties}{run}</w:r></w:p>"


def word_cell(cell, merge=""):
    properties = f'<w:gridSpan w:val="{cell.columns}"/>' if cell.columns > 1 else ""
    properties += merge
    if cell.header:
        properties += '<w:shd w:fill="E7EEF9"/>'
    return f'<w:tc><w:tcPr>{properties}</w:tcPr>{paragraph(cell.text, header=cell.header)}</w:tc>'


def word_table(table):
    rows = [{} for _ in table.rows]
    width = 0
    for y, x, cell, height in positioned(table):
        width = max(width, x + cell.columns)
        rows[y][x] = (cell.columns, word_cell(cell, '<w:vMerge w:val="restart"/>' if height > 1 else ""))
        for row in rows[y + 1:y + height]:
            row[x] = (cell.columns, word_cell(Cell("", cell.columns), "<w:vMerge/>"))
    borders = "".join(f'<w:{side} w:val="single" w:sz="4" w:color="B7C4D8"/>'
                      for side in ("top", "left", "bottom", "right", "insideH", "insideV"))
    grid = f'<w:gridCol w:w="{max(1, 9360 // width)}"/>' * width
    parts = [f'<w:tbl><w:tblPr><w:tblBorders>{borders}</w:tblBorders></w:tblPr><w:tblGrid>{grid}</w:tblGrid>']
    for row in rows:
        parts.append("<w:tr>")
        x = 0
        while x < width:
            columns, cell_xml = row.get(x, (1, word_cell(Cell(""))))
            parts.append(cell_xml)
            x += columns
        parts.append("</w:tr>")
    return "".join(parts) + "</w:tbl>"


def docx(blocks):
    body = "".join(word_table(block) if isinstance(block, Table) else paragraph(block[1], block[0])
                   for block in blocks)
    document = f'<w:document xmlns:w="{WORD}"><w:body>{body}</w:body></w:document>'
    return package("word/document.xml", [
        ("word/document.xml", "wordprocessingml.document.main", document),
    ])


def address(row, col):
    label = ""
    col += 1
    while col:
        col, remainder = divmod(col - 1, 26)
        label = chr(65 + remainder) + label
    return f"{label}{row + 1}"


def xlsx(tables):
    entries, sheets, links = [], [], []
    for i, table in enumerate(tables, 1):
        if len(table.rows) > 1048576:
            raise ValueError("Table has too many rows for Excel.")
        rows = [[] for _ in table.rows]
        merges = []
        for y, x, cell, height in positioned(table):
            ref = address(y, x)
            if height > 1 or cell.columns > 1:
                merges.append(f'<mergeCell ref="{ref}:{address(y + height - 1, x + cell.columns - 1)}"/>')
            rows[y].append(f'<c r="{ref}" t="inlineStr"><is><t xml:space="preserve">{xml_text(cell.text)}</t></is></c>')
        data = "".join(f'<row r="{y}">{"".join(row)}</row>' for y, row in enumerate(rows, 1))
        merged = f'<mergeCells count="{len(merges)}">{"".join(merges)}</mergeCells>' if merges else ""
        worksheet = f'<worksheet xmlns="{SHEET}"><sheetData>{data}</sheetData>{merged}</worksheet>'
        name = f"worksheets/sheet{i}.xml"
        entries.append((f"xl/{name}", "spreadsheetml.worksheet", worksheet))
        sheets.append(f'<sheet name="Table {i}" sheetId="{i}" r:id="rId{i}"/>')
        links.append(f'<Relationship Id="rId{i}" Type="{DOCREL}/worksheet" Target="{name}"/>')
    workbook = f'<workbook xmlns="{SHEET}" xmlns:r="{DOCREL}"><sheets>{"".join(sheets)}</sheets></workbook>'
    entries.extend([
        ("xl/workbook.xml", "spreadsheetml.sheet.main", workbook),
        ("xl/_rels/workbook.xml.rels", None, f'<Relationships xmlns="{RELS}">{"".join(links)}</Relationships>'),
    ])
    return package("xl/workbook.xml", entries)
